function suma(nums) {
  return nums.reduce((t, n) => t + n, 0)
}

function frecuencia(palabras) {
  const conteo = {}
  for (const p of palabras) conteo[p] = (conteo[p] || 0) + 1
  return conteo
}

function anagrama(a, b) {
  const ordenar = (s) => [...s].sort().join("")
  return ordenar(a) === ordenar(b)
}

function fizzbuzz(n) {
  const out = []
  for (let i = 1; i <= n; i++) {
    if (i % 15 === 0) out.push("FizzBuzz")
    else if (i % 3 === 0) out.push("Fizz")
    else if (i % 5 === 0) out.push("Buzz")
    else out.push(i)
  }
  return out
}

function masLarga(palabras) {
  let mejor = ""
  for (const p of palabras) if (p.length > mejor.length) mejor = p
  return mejor
}

function capicua(texto) {
  const limpio = texto.toLowerCase().replace(/\s/g, "")
  return limpio === [...limpio].reverse().join("")
}

